                                    if (skill == 'qyhc_dili' || skill == 'jiu') return false;
                                    var info = get.info(skill);
                                    if (!info || !lib.translate[skill] || lib.translate[skill] == '' || !lib.translate[`${skill}_info`] || lib.translate[`${skill}_info`] == '') return false;
                                    if (info.zhuSkill) return player.hasZhuSkill(skill);
