            fanyi: {
                name: qyhcCL.qyhc_style_func([1, 134, 255]) + 'translate库互译</span>',
                clear: true,
                onclick() {
                    qyhcCL.YUHENG(this);
                    if (this.ready) return;
                    var that = this;
                    game.prompt('请输入要翻译的内容(多个请用,隔开(半角逗号))<br>输入中文:若行首有:#～不区分大小写;@～包含该内容;%～被该内容包含;在这三个之后有~则表示计入info库', function (str) {
                        if (str == '!@#$%^&*()') game.writeFile("<html><head><title>翻译结果</title></head><body><p style='text-align:center;'><font size='20' color='FF3105'><b>未进行过有效翻译</b></font></p><p style='text-align:center;' onclick='window.close();'><font size='20' color='FF3105'><b>ⓧ</b></font></p><p style='text-align:center;'></body></html>", 'extension/群英荟萃乀摧林/layout', 'find.html', () => { });
                        else if (str) {
                            var arr = str.split('');
                            var value = 0;
                            while (arr[0]) {
                                if (arr[0] == '#') value++;
                                else if (arr[0] == '@') value += 2;
                                else if (arr[0] == '%') value += 4;
                                else break;
                                arr.shift();
                            }
                            if (arr[0] == '~') {
                                var oninfo = true;
                                arr.shift();
                            }
                            str = arr.join('');
                            var func = function (str, value) {
                                var equal = function (a, b, value) {
                                    if (value % 2 > 0) ((a = a.toLowerCase()), (b = b.toLowerCase()));
                                    if (a == b) return true;
                                    if (value % 4 > 1 && a.includes(b)) return true;
                                    if (value % 8 > 3 && b.includes(a)) return true;
                                    return false;
                                };
                                var SRr = '';
                                if (lib.translate[str]) {
                                    SRr += '〖' + str + '|' + lib.translate[str] + '〗';
                                    if (lib.translate[`${str}_info`]) SRr += lib.translate[`${str}_info`];
                                    else if (lib.character[str]) SRr += lib.character[str];
                                    SRr += '<br>';
                                }
                                for (var i in lib.translate)
                                    if (lib.translate[i])
                                        if ((oninfo || i.indexOf('_info') == -1) && equal(lib.translate[i], str, value)) {
                                            SRr += '〖' + i + '|' + lib.translate[i] + '〗';
                                            if (lib.translate[`${i}_info`]) SRr += lib.translate[`${i}_info`];
                                            else if (lib.character[i]) SRr += lib.character[i];
                                            SRr += '<br>';
                                        }
                                return SRr;
                            };
                            var SRr = '';
                            var list = str.split(',');
                            for (var i of list) SRr += func(i, value);
                            if (SRr.length) {
                                SRr = "<html><head><title>翻译结果</title></head><body><p style='text-align:right;margin-right:20px;'><input type='button' name='close' value='关闭(按Alt+Esc可最小化本窗口)' onclick='window.close();' /></p><p style='text-align:left;margin:25px;'><font size='5'>" + SRr.slice(0, -4) + '</font></p></body></html>';
                                game.saveConfig('extension_群英荟萃乀摧林_find', SRr);
                                game.writeFile(SRr, 'extension/群英荟萃乀摧林/layout', 'find.html', () => { });
                            } else {
                                that.innerHTML = qyhcCL.qyhc_style_func([243, 35, 35]) + '找不到您输入内容的对应翻译!</span>';
                                setTimeout(() => {
                                    that.innerHTML = qyhcCL.qyhc_style_func([1, 134, 255]) + '输入要翻译的内容</span>';
                                    delete that.ready;
                                }, 1600);
                                return;
                            }
                            qyhcCL.openWindow('find');
                        }
                    });
                },
            },
